package com.bechir.salati;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.webkit.*;import java.util.*;
public class MainActivity extends Activity {
 WebView web; LocationManager lm; static final int REQ=41;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff0c1939);getWindow().setNavigationBarColor(0xff0c1939);web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.addJavascriptInterface(new Bridge(),"AndroidLocation");web.setWebViewClient(new WebViewClient());web.loadUrl("file:///android_asset/index.html");}
 public class Bridge {@JavascriptInterface public void requestLocation(){runOnUiThread(()->locate());}}
 void locate(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED && checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},REQ);return;} lm=(LocationManager)getSystemService(LOCATION_SERVICE);try{String provider=lm.isProviderEnabled(LocationManager.GPS_PROVIDER)?LocationManager.GPS_PROVIDER:LocationManager.NETWORK_PROVIDER; if(!lm.isProviderEnabled(provider)){error("فعّل خدمة الموقع GPS من إعدادات الهاتف.");return;} lm.requestSingleUpdate(provider,new LocationListener(){public void onLocationChanged(Location p){double lat=p.getLatitude(),lon=p.getLongitude();new Thread(()->{String city="";String country="";try{Geocoder g=new Geocoder(MainActivity.this,new Locale("ar"));java.util.List<Address> a=g.getFromLocation(lat,lon,1);if(a!=null&&!a.isEmpty()){Address addr=a.get(0);country=addr.getCountryCode();city=addr.getLocality();if(city==null||city.isEmpty())city=addr.getSubAdminArea();if(city==null||city.isEmpty())city=addr.getAdminArea();}}catch(Exception ignored){}String safe=org.json.JSONObject.quote(city==null?"":city);String safeCountry=org.json.JSONObject.quote(country==null?"":country);runOnUiThread(()->web.evaluateJavascript("window.salatiNativeLocation("+lat+","+lon+","+p.getAccuracy()+","+safe+","+safeCountry+")",null));}).start();}public void onProviderDisabled(String p){error("خدمة الموقع غير مفعلة.");}},null);}catch(Exception e){error("تعذر الحصول على الموقع. تحقق من أذونات التطبيق.");}}
 void error(String s){web.evaluateJavascript("window.salatiNativeError("+org.json.JSONObject.quote(s)+")",null);}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==REQ){boolean ok=false;for(int v:g)if(v==PackageManager.PERMISSION_GRANTED)ok=true;if(ok)locate();else error("تم رفض إذن الموقع. يمكنك اختيار المدينة يدويًا.");}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}